CREATE DATABASE IF NOT EXISTS hms CHARACTER SET utf8mb4;
USE hms;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80),username VARCHAR(40) UNIQUE,email VARCHAR(100) UNIQUE,password VARCHAR(255),role ENUM('admin','doctor','receptionist'));
CREATE TABLE patients(id INT AUTO_INCREMENT PRIMARY KEY,patient_code VARCHAR(12) UNIQUE,full_name VARCHAR(100) NOT NULL,dob DATE NOT NULL,gender ENUM('Male','Female','Other') NOT NULL,phone VARCHAR(20) NOT NULL,email VARCHAR(100),address VARCHAR(255) NOT NULL,blood_group VARCHAR(4),emergency_contact VARCHAR(20),reg_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE appointments(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,doctor VARCHAR(80) NOT NULL,appt_date DATE NOT NULL,appt_time TIME NOT NULL,reason VARCHAR(255),status ENUM('Scheduled','Completed','Cancelled') DEFAULT 'Scheduled',FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
CREATE TABLE records(id INT AUTO_INCREMENT PRIMARY KEY,patient_id INT NOT NULL,visit_date DATE NOT NULL,symptoms TEXT,diagnosis TEXT,treatment TEXT,doctor VARCHAR(80),follow_up DATE NULL,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE);
